//! Byte-compatibility of the Rust session store with sessions written by the
//! real TypeScript pi (the P4 exit criterion).
//!
//! The fixtures under `tests/fixtures/golden/` are JSONL v3 session files
//! generated by `@earendil-works/pi-coding-agent@1.5.2` in print mode against
//! a local llama-swap endpoint (an `openai-completions` provider declared in a
//! synthetic `models.json`). Every prompt is synthetic and each run used a
//! fresh `PI_CODING_AGENT_DIR` / `PI_CODING_AGENT_SESSION_DIR`, so no real
//! data is involved; the files are committed verbatim, byte for byte as pi
//! wrote them.
//!
//! The criterion is that the Rust store round-trips these files
//! byte-identically: parse with the store's loader, re-serialize with the
//! store's writer, compare against the committed bytes. The typed
//! [`SessionEntry`] views must decode the expected entry kinds and fields.
//! Byte equality rides on the canonical [`Record`] form: TS writes nested
//! message objects in write-site key order (assistant `usage` before
//! `responseId`, system `timestamp` before `toolsAdded`), which a typed view
//! re-serializes in Rust declaration order, so message entries are asserted
//! against the raw records while pi's flat entries (whose field order matches
//! the Rust declaration order) are additionally asserted to rewrite exactly
//! through the typed view.

use std::fs;
use std::path::{Path, PathBuf};

use pi_agent::AgentMessage;
use pi_ai::types::{AssistantContent, StopReason, StringOrTextBlocks, ThinkingLevel, UserContent};
use pi_coding_agent::session::{
    Record, SessionEntry, SessionManager, load_entries_from_file, read_session_header,
    serialize_entries,
};

const PLAIN: &str = "01-plain-user-assistant.jsonl";
const TOOL_READ: &str = "02-tool-read-round-trip.jsonl";
const MODEL_THINKING: &str = "03-model-change-thinking-low.jsonl";
const MULTI_TURN: &str = "04-multi-turn-with-name.jsonl";
const RESUME_THINKING: &str = "05-resume-thinking-level-change.jsonl";

/// Fixture name and the cwd pi recorded in its header.
const FIXTURES: [(&str, &str); 5] = [
    (PLAIN, "/tmp/golden-cwd/01-plain"),
    (TOOL_READ, "/tmp/golden-cwd/02-tool-read"),
    (MODEL_THINKING, "/tmp/golden-cwd/03-model-thinking"),
    (MULTI_TURN, "/tmp/golden-cwd/04-multi-turn"),
    (RESUME_THINKING, "/tmp/golden-cwd/05-resume-thinking"),
];

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/golden")
}

fn fixture_text(name: &str) -> String {
    fs::read_to_string(fixtures_dir().join(name)).unwrap()
}

fn load_fixture(name: &str) -> Vec<Record> {
    load_entries_from_file(&fixtures_dir().join(name)).unwrap()
}

fn typed_entries(records: &[Record]) -> Vec<SessionEntry> {
    records.iter().map(SessionEntry::from_record).collect()
}

fn kinds(entries: &[SessionEntry]) -> Vec<&str> {
    entries.iter().map(SessionEntry::kind).collect()
}

/// Every fixture is one linear branch: the first entry is a root and each
/// later entry points at its physical predecessor.
fn assert_linear_chain(records: &[Record]) {
    assert_eq!(records[0].kind(), "session");
    assert_eq!(records[1].parent_id(), None, "entry 1 must be a root");
    for (index, record) in records.iter().enumerate().skip(2) {
        assert_eq!(
            record.parent_id(),
            Some(records[index - 1].id().unwrap_or("")),
            "entry {index} breaks the linear chain"
        );
    }
}

/// The P4 exit criterion: the store's parse/serialize pair reproduces the
/// committed bytes exactly.
fn assert_byte_round_trip(name: &str, records: &[Record]) {
    let original = fixture_text(name);
    assert!(original.ends_with('\n'), "pi ends the file with a newline");
    assert_eq!(serialize_entries(records), original);
}

/// pi's flat entries carry their payload in the same order the Rust views
/// declare, so the typed view must rewrite them byte-identically. `message`
/// entries are exempt (nested write-site key order, see the module doc).
fn assert_simple_typed_views_rewrite(records: &[Record]) {
    for record in records {
        if record.kind() == "message" {
            continue;
        }
        let entry = SessionEntry::from_record(record);
        assert_eq!(
            entry.to_record().to_line(),
            record.to_line(),
            "typed view of a {} entry changed the line",
            record.kind()
        );
    }
}

#[test]
fn golden_headers_decode_as_v3_with_synthetic_cwds() {
    let ids = [
        "01a1e4e7-d1ff-717f-baf9-ad5cd6840248",
        "01a1e4e8-62c2-7148-a593-b1f47d8cb892",
        "01a1e4e8-9bc3-71d3-a1ae-425e5503b481",
        "01a1e4e8-da35-7789-82da-852d30b04c0f",
        "01a1e4e9-05a2-7018-8622-e30713cef684",
    ];
    for ((name, cwd), id) in FIXTURES.iter().copied().zip(ids) {
        let header = read_session_header(&fixtures_dir().join(name))
            .unwrap()
            .unwrap();
        assert_eq!(header.version, Some(3), "{name}");
        assert_eq!(header.id, id, "{name}");
        assert_eq!(header.cwd, cwd, "{name}");
        assert_eq!(header.parent_session, None, "{name}");
    }
}

#[test]
fn golden_plain_exchange_round_trips_byte_exactly() {
    let records = load_fixture(PLAIN);
    let entries = typed_entries(&records);
    assert_eq!(
        kinds(&entries),
        [
            "session",
            "model_change",
            "thinking_level_change",
            "message",
            "message",
            "message",
        ]
    );
    assert_linear_chain(&records);
    assert_byte_round_trip(PLAIN, &records);
    assert_simple_typed_views_rewrite(&records);

    let SessionEntry::ModelChange(change) = &entries[1] else {
        panic!("expected model_change");
    };
    assert_eq!(change.base.parent_id, None);
    assert_eq!(change.provider, "llama-swap");
    assert_eq!(change.model_id, "qwen3.8-4b");

    let SessionEntry::ThinkingLevelChange(level) = &entries[2] else {
        panic!("expected thinking_level_change");
    };
    assert_eq!(level.thinking_level, "off");

    let SessionEntry::Message(entry) = &entries[3] else {
        panic!("expected the system message");
    };
    let AgentMessage::System(system) = &entry.message else {
        panic!("expected a system message");
    };
    let StringOrTextBlocks::Text(content) = &system.content else {
        panic!("expected string system content");
    };
    assert_eq!(content, "");
    let sections = system.sections.as_ref().unwrap();
    assert_eq!(sections.len(), 6);
    for section in ["preamble", "tools", "rules", "docs", "skills", "cwd"] {
        assert!(sections.contains_key(section), "missing section {section}");
    }
    let tools = system.tools_added.as_ref().unwrap();
    assert_eq!(tools.len(), 4);
    assert_eq!(tools[0].name, "read");

    let SessionEntry::Message(entry) = &entries[4] else {
        panic!("expected the user message");
    };
    let AgentMessage::User(user) = &entry.message else {
        panic!("expected a user message");
    };
    let UserContent::Blocks(blocks) = &user.content else {
        panic!("expected block user content");
    };
    assert_eq!(blocks.len(), 1);
    assert_eq!(
        blocks[0].as_text(),
        Some("What is 2 + 2? Reply with just the number.")
    );

    let SessionEntry::Message(entry) = &entries[5] else {
        panic!("expected the assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.api, "openai-completions");
    assert_eq!(assistant.provider, "llama-swap");
    assert_eq!(assistant.model, "qwen3.8-4b");
    assert_eq!(assistant.stop_reason, StopReason::Stop);
    assert_eq!(assistant.thinking_level, Some(ThinkingLevel::Off));
    assert_eq!(assistant.usage.input, 1036);
    assert_eq!(assistant.usage.output, 38);
    assert_eq!(assistant.usage.cache_read, 3049);
    assert_eq!(assistant.usage.cache_write, 0);
    assert_eq!(assistant.usage.reasoning, Some(0));
    assert_eq!(assistant.usage.total_tokens, 4123);
    assert_eq!(assistant.usage.cost.total_from_provider, Some(false));
    assert!(assistant.response_id.is_some());
    assert!(assistant.response_model.is_some());
    assert_eq!(assistant.raw_stop_reason.as_deref(), Some("stop"));
    assert!(assistant.duration_ms.is_some());
    assert_eq!(assistant.content.len(), 2);
    let AssistantContent::Thinking(thinking) = &assistant.content[0] else {
        panic!("expected a thinking block");
    };
    assert_ne!(thinking.thinking, "");
    assert_eq!(
        thinking.thinking_signature.as_deref(),
        Some("reasoning_content")
    );
    assert!(!thinking.redacted);
    assert_eq!(assistant.content[1].as_text(), Some("4"));
}

#[test]
fn golden_tool_round_trip_decodes_call_and_result() {
    let records = load_fixture(TOOL_READ);
    let entries = typed_entries(&records);
    assert_eq!(
        kinds(&entries),
        [
            "session",
            "model_change",
            "thinking_level_change",
            "message",
            "message",
            "message",
            "message",
            "message",
        ]
    );
    assert_linear_chain(&records);
    assert_byte_round_trip(TOOL_READ, &records);
    assert_simple_typed_views_rewrite(&records);

    let SessionEntry::Message(entry) = &entries[5] else {
        panic!("expected the tool-calling assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.stop_reason, StopReason::ToolUse);
    assert_eq!(assistant.content.len(), 2);
    let AssistantContent::ToolCall(call) = &assistant.content[1] else {
        panic!("expected a toolCall block");
    };
    assert_eq!(call.id, "UgVGz1W2J5mNkMzXPhPtbdI36GfUzwBk");
    assert_eq!(call.name, "read");
    assert_eq!(
        call.arguments.get("path").and_then(|value| value.as_str()),
        Some("notes.txt")
    );

    let SessionEntry::Message(entry) = &entries[6] else {
        panic!("expected the tool result");
    };
    let AgentMessage::ToolResult(result) = &entry.message else {
        panic!("expected a toolResult message");
    };
    assert_eq!(result.tool_call_id, "UgVGz1W2J5mNkMzXPhPtbdI36GfUzwBk");
    assert_eq!(result.tool_name, "read");
    assert!(!result.is_error);
    assert_eq!(result.duration_ms, Some(3));
    assert_eq!(result.timestamp, 1_794_841_798_869);
    assert_eq!(result.content.len(), 1);
    assert_eq!(
        result.content[0].as_text(),
        Some("alpha line\nbravo line\ncharlie line\n")
    );

    let SessionEntry::Message(entry) = &entries[7] else {
        panic!("expected the final assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.stop_reason, StopReason::Stop);
    assert_eq!(assistant.content[1].as_text(), Some("charlie line"));
}

#[test]
fn golden_second_model_and_low_thinking_are_recorded() {
    let records = load_fixture(MODEL_THINKING);
    let entries = typed_entries(&records);
    assert_eq!(
        kinds(&entries),
        [
            "session",
            "model_change",
            "thinking_level_change",
            "message",
            "message",
            "message",
        ]
    );
    assert_linear_chain(&records);
    assert_byte_round_trip(MODEL_THINKING, &records);
    assert_simple_typed_views_rewrite(&records);

    let SessionEntry::ModelChange(change) = &entries[1] else {
        panic!("expected model_change");
    };
    assert_eq!(change.provider, "llama-swap");
    assert_eq!(change.model_id, "bonsai-2-9b");

    let SessionEntry::ThinkingLevelChange(level) = &entries[2] else {
        panic!("expected thinking_level_change");
    };
    assert_eq!(level.thinking_level, "low");

    let SessionEntry::Message(entry) = &entries[5] else {
        panic!("expected the assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.model, "bonsai-2-9b");
    assert_eq!(assistant.thinking_level, Some(ThinkingLevel::Low));
    assert_eq!(assistant.stop_reason, StopReason::Stop);
    assert_eq!(assistant.content[1].as_text(), Some("8"));
}

#[test]
fn golden_multi_turn_session_keeps_session_info_and_two_turns() {
    let records = load_fixture(MULTI_TURN);
    let entries = typed_entries(&records);
    assert_eq!(
        kinds(&entries),
        [
            "session",
            "session_info",
            "model_change",
            "thinking_level_change",
            "message",
            "message",
            "message",
            "message",
            "message",
        ]
    );
    assert_linear_chain(&records);
    assert_byte_round_trip(MULTI_TURN, &records);
    assert_simple_typed_views_rewrite(&records);

    // `--name` lands before the model selection entries and roots the tree.
    let SessionEntry::SessionInfo(info) = &entries[1] else {
        panic!("expected session_info");
    };
    assert_eq!(info.base.parent_id, None);
    assert_eq!(info.name.as_deref(), Some("golden multi-turn"));

    let SessionEntry::ModelChange(change) = &entries[2] else {
        panic!("expected model_change");
    };
    assert_eq!(change.base.parent_id.as_deref(), Some(entries[1].id()));

    let prompts = [
        (5usize, "What is 10 - 4? Reply with just the number."),
        (
            7usize,
            "Now multiply that answer by 3. Reply with just the number.",
        ),
    ];
    for (index, text) in prompts {
        let SessionEntry::Message(entry) = &entries[index] else {
            panic!("expected a user message at {index}");
        };
        let AgentMessage::User(user) = &entry.message else {
            panic!("expected a user message at {index}");
        };
        let UserContent::Blocks(blocks) = &user.content else {
            panic!("expected block user content at {index}");
        };
        assert_eq!(blocks.len(), 1);
        assert_eq!(blocks[0].as_text(), Some(text));
    }
    for index in [6usize, 8usize] {
        let SessionEntry::Message(entry) = &entries[index] else {
            panic!("expected an assistant message at {index}");
        };
        let AgentMessage::Assistant(assistant) = &entry.message else {
            panic!("expected an assistant message at {index}");
        };
        assert_eq!(assistant.stop_reason, StopReason::Stop);
    }
    let SessionEntry::Message(entry) = &entries[6] else {
        panic!("expected the first assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.content[1].as_text(), Some("6"));
    let SessionEntry::Message(entry) = &entries[8] else {
        panic!("expected the second assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.content[1].as_text(), Some("18"));
}

#[test]
fn golden_resume_appends_mid_branch_thinking_level_change() {
    let records = load_fixture(RESUME_THINKING);
    let entries = typed_entries(&records);
    assert_eq!(
        kinds(&entries),
        [
            "session",
            "model_change",
            "thinking_level_change",
            "message",
            "message",
            "message",
            "thinking_level_change",
            "message",
            "message",
        ]
    );
    assert_linear_chain(&records);
    assert_byte_round_trip(RESUME_THINKING, &records);
    assert_simple_typed_views_rewrite(&records);

    // `-c --thinking low` records the switch after the first turn.
    let SessionEntry::ThinkingLevelChange(level) = &entries[6] else {
        panic!("expected the resumed thinking_level_change");
    };
    assert_eq!(level.thinking_level, "low");
    assert_eq!(level.base.parent_id.as_deref(), Some(entries[5].id()));

    let SessionEntry::Message(entry) = &entries[7] else {
        panic!("expected the follow-up user message");
    };
    let AgentMessage::User(user) = &entry.message else {
        panic!("expected a user message");
    };
    let UserContent::Blocks(blocks) = &user.content else {
        panic!("expected block user content");
    };
    assert_eq!(blocks.len(), 1);
    assert_eq!(
        blocks[0].as_text(),
        Some("Add 5 to your previous answer. Reply with just the number.")
    );

    let SessionEntry::Message(entry) = &entries[8] else {
        panic!("expected the follow-up assistant message");
    };
    let AgentMessage::Assistant(assistant) = &entry.message else {
        panic!("expected an assistant message");
    };
    assert_eq!(assistant.thinking_level, Some(ThinkingLevel::Low));
    assert_eq!(assistant.content[1].as_text(), Some("17"));
}

#[test]
fn golden_fixtures_open_in_the_manager_without_a_rewrite() {
    for (name, cwd) in FIXTURES {
        let records = load_fixture(name);
        let dir = tempfile::Builder::new()
            .prefix("pi-rs-golden-open-")
            .tempdir()
            .unwrap();
        let copy = dir.path().join(name);
        fs::copy(fixtures_dir().join(name), &copy).unwrap();

        let manager = SessionManager::open(&copy, None, None).unwrap();
        // The header is not a tree entry; the manager tracks the rest.
        assert_eq!(manager.get_entry_count(), records.len() - 1, "{name}");
        assert_eq!(manager.get_cwd(), Path::new(cwd), "{name}");

        let expected = typed_entries(&records[1..]);
        assert_eq!(kinds(&manager.get_entries()), kinds(&expected), "{name}");
        let branch = manager.get_branch(None).unwrap();
        assert_eq!(kinds(&branch), kinds(&expected), "{name}");
        assert_eq!(
            manager.get_leaf_id(),
            expected.last().map(SessionEntry::id),
            "{name}"
        );

        // The branch's raw records (everything but the header, on a linear
        // fixture) re-serialize to the file's remainder byte for byte.
        let branch_records = manager.get_branch_records(None);
        let text = fixture_text(name);
        let (_, body) = text.split_once('\n').unwrap();
        assert_eq!(serialize_entries(&branch_records), body, "{name}");

        // Opening a current-version session must not touch the file.
        assert_eq!(fs::read_to_string(&copy).unwrap(), fixture_text(name));
    }
}
